        internal List<byte> Buffer => _data;

        /// <summary>take_bytes(n=None) (Python 3.15): the first n bytes (all of them) as bytes, removed from the bytearray.</summary>
        public PyBytes take_bytes(long? n = null)
        {
            int count = n == null ? _data.Count : (int)(n < 0 ? Math.Max(0, _data.Count + n.Value) : Math.Min(n.Value, _data.Count));
            if (n != null && (n > _data.Count || n < -_data.Count)) throw new IndexOutOfRangeException("can't take more bytes than are in the bytearray");
            var taken = _data.GetRange(0, count).ToArray();
            _data.RemoveRange(0, count);
            return new PyBytes(taken);
        }
        public static implicit operator byte[](PyByteArray b) => b.ToArray();

        public int Count => _data.Count;
        long IPyLen.__len__() => _data.Count;
        public bool IsReadOnly => false;
        public long this[long i] { get => _data[ByteOps.Pos(i, _data.Count)]; set => _data[ByteOps.Pos(i, _data.Count)] = ByteOps.Byte(value); }
        public long this[int i] { get => _data[ByteOps.Pos(i, _data.Count)]; set => _data[ByteOps.Pos(i, _data.Count)] = ByteOps.Byte(value); }
        long IList<long>.this[int i] { get => _data[i]; set => _data[i] = ByteOps.Byte(value); }
        long IReadOnlyList<long>.this[int i] => _data[i];
        public IEnumerator<long> GetEnumerator() { for (int i = 0; i < _data.Count; i++) yield return _data[i]; }
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
        public int IndexOf(long item) => _data.IndexOf(ByteOps.Byte(item));
        public void Insert(int index, long item) => _data.Insert(index, ByteOps.Byte(item));
        public void RemoveAt(int index) => _data.RemoveAt(index);
        public void Add(long item) => _data.Add(ByteOps.Byte(item));
        public void Clear() => _data.Clear();
        public bool Contains(long item) => item >= 0 && item <= 255 && _data.Contains((byte)item);
        public void CopyTo(long[] array, int arrayIndex) { foreach (var b in _data) array[arrayIndex++] = b; }
        public bool Remove(long item) => _data.Remove(ByteOps.Byte(item));

        public void append(long b) => _data.Add(ByteOps.Byte(b));
        public void extend(object? items) => _data.AddRange(ByteOps.From(items));
        public void insert(long i, long b) => _data.Insert((int)Math.Clamp(i < 0 ? i + _data.Count : i, 0, _data.Count), ByteOps.Byte(b));
        public long pop(long i = -1) { int k = ByteOps.Pos(i, _data.Count); byte b = _data[k]; _data.RemoveAt(k); return b; }
        public void remove(long b) { if (!_data.Remove(ByteOps.Byte(b))) throw new ArgumentException("value not found in bytearray"); }
        public void reverse() => _data.Reverse();
        public void clear() => _data.Clear();
        public PyByteArray copy() => new PyByteArray(_data);
        public PyByteArray Slice(long? start, long? stop, long step = 1) => new PyByteArray(ByteOps.Slice(_data.ToArray(), start, stop, step));
        public string decode(string encoding = "utf-8", string errors = "strict") => ByteOps.Decode(_data.ToArray(), encoding, errors);
        public string hex(string? sep = null) => ByteOps.Hex(_data.ToArray(), sep);
        public long find(PyBytes sub, long start = 0, long? end = null) => ByteOps.Find(_data.ToArray(), sub.Data, start, end, false);
        public long count(long b) => _data.Count(x => x == b);

        // ── bytes' methods: computed on a snapshot; those returning bytes return a bytearray, as in Python ──
        public static implicit operator PyBytes(PyByteArray b) => new PyBytes(b.ToArray());
        PyBytes B => new PyBytes(_data.ToArray());
        static PyByteArray A(PyBytes b) => new PyByteArray(b.Data);
        static List<PyByteArray> A(List<PyBytes> bs) => bs.Select(A).ToList();
        static (PyByteArray, PyByteArray, PyByteArray) A((PyBytes, PyBytes, PyBytes) t) => (A(t.Item1), A(t.Item2), A(t.Item3));
        public long find(long b, long start = 0, long? end = null) => B.find(b, start, end);
        public long rfind(PyBytes sub, long start = 0, long? end = null) => B.rfind(sub, start, end);
        public long index(PyBytes sub, long start = 0, long? end = null) => B.index(sub, start, end);
        public long index(long b, long start = 0, long? end = null) => B.index(b, start, end);
        public long rindex(PyBytes sub, long start = 0, long? end = null) => B.rindex(sub, start, end);
        public long count(PyBytes sub) => B.count(sub);
        public bool startswith(PyBytes prefix) => B.startswith(prefix);
        public bool endswith(PyBytes suffix) => B.endswith(suffix);
        public bool isdigit() => B.isdigit();
        public bool isalpha() => B.isalpha();
        public bool isalnum() => B.isalnum();
        public bool isspace() => B.isspace();
        public bool islower() => B.islower();
        public bool isupper() => B.isupper();
        public bool isascii() => B.isascii();
        public bool istitle() => B.istitle();
        public PyByteArray upper() => A(B.upper());
        public PyByteArray lower() => A(B.lower());
        public PyByteArray capitalize() => A(B.capitalize());
        public PyByteArray swapcase() => A(B.swapcase());
        public PyByteArray title() => A(B.title());
        public static PyBytes maketrans(object from, object to) => PyBytes.maketrans(from, to);
        public PyByteArray translate(object? table, object? delete = null) => A(B.translate(table, delete));

        public PyByteArray strip(PyBytes? chars = null) => A(B.strip(chars));
        public PyByteArray lstrip(PyBytes? chars = null) => A(B.lstrip(chars));
        public PyByteArray rstrip(PyBytes? chars = null) => A(B.rstrip(chars));
        public PyByteArray replace(PyBytes old, PyBytes @new, long count = -1) => A(B.replace(old, @new, count));
        public PyByteArray center(long width, PyBytes? fillbyte = null) => A(B.center(width, fillbyte));
        public PyByteArray ljust(long width, PyBytes? fillbyte = null) => A(B.ljust(width, fillbyte));
        public PyByteArray rjust(long width, PyBytes? fillbyte = null) => A(B.rjust(width, fillbyte));
        public PyByteArray zfill(long width) => A(B.zfill(width));
        public PyByteArray removeprefix(PyBytes prefix) => A(B.removeprefix(prefix));
        public PyByteArray removesuffix(PyBytes suffix) => A(B.removesuffix(suffix));
        public PyByteArray expandtabs(long tabsize = 8) => A(B.expandtabs(tabsize));
        public PyByteArray join(IEnumerable parts) => A(B.join(parts));
        public List<PyByteArray> split(PyBytes? sep = null, long maxsplit = -1) => A(B.split(sep, maxsplit));
        public List<PyByteArray> rsplit(PyBytes? sep = null, long maxsplit = -1) => A(B.rsplit(sep, maxsplit));
        public List<PyByteArray> splitlines(bool keepends = false) => A(B.splitlines(keepends));
        public (PyByteArray, PyByteArray, PyByteArray) partition(PyBytes sep) => A(B.partition(sep));
        public (PyByteArray, PyByteArray, PyByteArray) rpartition(PyBytes sep) => A(B.rpartition(sep));
        public static PyByteArray operator +(PyByteArray a, PyBytes b) => new PyByteArray(a._data.Concat(b.Data));
        public static PyByteArray operator +(PyByteArray a, PyByteArray b) => new PyByteArray(a._data.Concat(b._data));
        public PyByteArray __iadd__(object? b) { extend(b); return this; }
        public override bool Equals(object? obj) => obj is PyByteArray a ? _data.SequenceEqual(a._data) : obj is PyBytes b ? _data.SequenceEqual(b.Data) : obj is global::memoryview m && m.Equals(this);
        public override int GetHashCode() => throw new InvalidCastException("unhashable type: 'bytearray'");
        public string __repr__() => "bytearray(" + ByteOps.Repr(_data.ToArray()) + ")";
        public override string ToString() => __repr__();
        public bool __contains__(object? x) => x is PyBytes b ? _data.ToArray().AsSpan().IndexOf(b.Data) >= 0 : _data.Contains(ByteOps.Byte(x));
    }

    /// <summary>A hashlib hash object: update() data, digest() / hexdigest() at any point, copy().</summary>
    internal sealed class PyHash
    {
        readonly System.IO.MemoryStream _data = new System.IO.MemoryStream();
        public readonly string name;
        public PyHash(string name, object? data = null) { this.name = name; if (data != null) update(data); }
        public long digest_size => name switch { "md5" => 16, "sha1" => 20, "sha256" => 32, "sha384" => 48, "sha512" => 64, _ => 0 };
        public long block_size => name is "sha384" or "sha512" ? 128 : 64;
        public object? update(object? data)
        {
            if (data is string) throw new InvalidCastException("Strings must be encoded before hashing");
            _data.Write(ByteOps.Buffer(data));
            return null;
        }
        public PyBytes digest()
        {
            var bytes = _data.ToArray();
            return new PyBytes(name switch
            {
                "md5" => System.Security.Cryptography.MD5.HashData(bytes),
                "sha1" => System.Security.Cryptography.SHA1.HashData(bytes),
                "sha256" => System.Security.Cryptography.SHA256.HashData(bytes),
                "sha384" => System.Security.Cryptography.SHA384.HashData(bytes),
                "sha512" => System.Security.Cryptography.SHA512.HashData(bytes),
                _ => throw new ArgumentException("unsupported hash type " + name),
            });
        }
        public string hexdigest() => digest().hex();
        public PyHash copy() { var h = new PyHash(name); h._data.Write(_data.ToArray()); return h; }
        public override string ToString() => $"<{name} _hashlib.HASH object @ 0x{System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(this):x}>";
    }
}

namespace Typhon.Stdlib
{
    using System;
    using System.Collections.Generic;
    using System.Globalization;
    using System.Linq;
    using System.Numerics;
    using Typhon.Runtime;

    /// <summary>hashlib: md5, sha1, sha256, sha384, sha512 (on .NET's implementations).</summary>
    internal static class hashlib
    {
        public static PyHash md5(object? data = null, bool usedforsecurity = true) => new PyHash("md5", data);
        public static PyHash sha1(object? data = null, bool usedforsecurity = true) => new PyHash("sha1", data);
        public static PyHash sha256(object? data = null, bool usedforsecurity = true) => new PyHash("sha256", data);
        public static PyHash sha384(object? data = null, bool usedforsecurity = true) => new PyHash("sha384", data);
        public static PyHash sha512(object? data = null, bool usedforsecurity = true) => new PyHash("sha512", data);
        public static PyHash @new(string name, object? data = null) => new PyHash(name.ToLowerInvariant().Replace("-", ""), data);
        public static readonly frozenset<string> algorithms_available = new frozenset<string>(new[] { "md5", "sha1", "sha256", "sha384", "sha512" });
        public static readonly frozenset<string> algorithms_guaranteed = algorithms_available;
    }

    /// <summary>struct: pack values into bytes and unpack them, by format strings (byte order, sizes and alignment like C).</summary>
    internal static class struct_
    {
        /// <summary>struct.error</summary>
        internal sealed class error : ArgumentException { public error(string msg) : base(msg) { } }

        sealed class Item { public char Code; public int Count; public int Size; public int Offset; }

        static readonly Dictionary<string, Struct> Cache = new Dictionary<string, Struct>();
        static Struct Of(string fmt) { lock (Cache) return Cache.TryGetValue(fmt, out var s) ? s : Cache[fmt] = new Struct(fmt); }

        /// <summary>struct.Struct(format): a compiled format.</summary>
        internal sealed class Struct
        {
            public readonly string format;
            public readonly long size;
            readonly List<Item> _items = new List<Item>();
            readonly bool _little;

            public Struct(string format)
            {
                this.format = format;
                int i = 0;
                char order = format.Length > 0 && "@=<>!".IndexOf(format[0]) >= 0 ? format[i++] : '@';
                bool native = order == '@';
                _little = order == '<' || (order == '@' || order == '=') && BitConverter.IsLittleEndian;
                int offset = 0;
                while (i < format.Length)
                {
                    char ch = format[i];
                    if (char.IsWhiteSpace(ch)) { i++; continue; }
                    int count = 1;
                    if (char.IsAsciiDigit(ch))
                    {
                        count = 0;
                        while (i < format.Length && char.IsAsciiDigit(format[i])) count = count * 10 + (format[i++] - '0');
                        if (i >= format.Length) throw new error("repeat count given without format specifier");
                        ch = format[i];
                    }
                    i++;
                    int sz = SizeOf(ch, native);
                    if (sz < 0) throw new error("bad char in struct format");
                    if (native && sz > 1 && ch != 's' && ch != 'p' && ch != 'x') offset = (offset + sz - 1) / sz * sz;
                    if (ch == 's' || ch == 'p') { _items.Add(new Item { Code = ch, Count = count, Size = count, Offset = offset }); offset += count; }
                    else if (ch == 'x') offset += count;
                    else for (int k = 0; k < count; k++) { _items.Add(new Item { Code = ch, Count = 1, Size = sz, Offset = offset }); offset += sz; }
                }
                size = offset;
            }

            static int SizeOf(char c, bool native) => c switch
            {
                'x' or 'c' or 'b' or 'B' or '?' or 's' or 'p' => 1,
                'h' or 'H' or 'e' => 2,
                'i' or 'I' or 'f' => 4,
                'l' or 'L' => native && !OperatingSystem.IsWindows() ? 8 : 4,
                'q' or 'Q' or 'd' => 8,
                'n' or 'N' or 'P' => native ? 8 : -1,
                _ => -1,
            };

            /// <summary>The number of values pack takes and unpack returns.</summary>
            public int ItemCount => _items.Count;

            public PyBytes pack(params object?[] values)
            {
                if (values.Length != _items.Count) throw new error($"pack expected {_items.Count} items for packing (got {values.Length})");
                var buf = new byte[size];
                for (int k = 0; k < values.Length; k++) Write(buf, 0, _items[k], values[k]);
                return new PyBytes(buf);
            }

            public void pack_into(PyByteArray buffer, long offset, params object?[] values)
            {
                var packed = pack(values).Data;
                for (int k = 0; k < packed.Length; k++) buffer[offset + k] = packed[k];
            }

            public PyTuple<object?> unpack(object buffer)
            {
                var data = ByteOps.From(buffer);
                if (data.Length != size) throw new error($"unpack requires a buffer of {size} bytes");
                return Read(data, 0);
            }

            public PyTuple<object?> unpack_from(object buffer, long offset = 0)
            {
                var data = ByteOps.From(buffer);
                if (offset < 0) offset += data.Length;
                if (data.Length - offset < size) throw new error($"unpack_from requires a buffer of at least {size + offset} bytes");
                return Read(data, (int)offset);
            }

            public IEnumerable<PyTuple<object?>> iter_unpack(object buffer)
            {
                var data = ByteOps.From(buffer);
                if (size == 0 || data.Length % size != 0) throw new error($"iterative unpacking requires a buffer of a multiple of {size} bytes");
                for (int off = 0; off < data.Length; off += (int)size) yield return Read(data, off);
            }

            PyTuple<object?> Read(byte[] data, int at)
            {
                var r = new object?[_items.Count];
                for (int k = 0; k < r.Length; k++) r[k] = ReadItem(data, at + _items[k].Offset, _items[k]);
                return new PyTuple<object?>(r);
            }

            ulong ReadUInt(byte[] d, int at, int n)
            {
                ulong v = 0;
                for (int k = 0; k < n; k++) v |= (ulong)d[at + (_little ? k : n - 1 - k)] << (8 * k);
                return v;
            }

            object? ReadItem(byte[] d, int at, Item it)
            {
                switch (it.Code)
                {
                    case 'c': return new PyBytes(new[] { d[at] });
                    case 's': return new PyBytes(d[at..(at + it.Size)]);
                    case 'p': { int n = Math.Min(d[at], it.Size - 1); return new PyBytes(d[(at + 1)..(at + 1 + n)]); }
                    case '?': return d[at] != 0;
                    case 'e': return (double)BitConverter.UInt16BitsToHalf((ushort)ReadUInt(d, at, 2));
                    case 'f': return (double)BitConverter.Int32BitsToSingle((int)ReadUInt(d, at, 4));
                    case 'd': return BitConverter.Int64BitsToDouble((long)ReadUInt(d, at, 8));
                }
                ulong u = ReadUInt(d, at, it.Size);
                bool signed = char.IsLower(it.Code);
                if (!signed) return u <= long.MaxValue ? (object)(long)u : new BigInteger(u);
                int bits = it.Size * 8;
                long s = bits == 64 ? (long)u : (long)(u << (64 - bits)) >> (64 - bits);
                return s;
            }

            void Write(byte[] buf, int at, Item it, object? v)
            {
                at += it.Offset;
                switch (it.Code)
                {
                    case 'c':
                    {
                        var b = ByteOps.From(v);
                        if (b.Length != 1) throw new error("char format requires a bytes object of length 1");
                        buf[at] = b[0];
                        return;
                    }
                    case 's': { var b = ByteOps.From(v); Array.Copy(b, 0, buf, at, Math.Min(b.Length, it.Size)); return; }
                    case 'p': { var b = ByteOps.From(v); int n = Math.Min(b.Length, Math.Min(255, it.Size - 1)); buf[at] = (byte)n; Array.Copy(b, 0, buf, at + 1, n); return; }
                    case '?': buf[at] = Builtins.truthy(v) ? (byte)1 : (byte)0; return;
                    case 'e': WriteUInt(buf, at, 2, BitConverter.HalfToUInt16Bits((Half)ToDouble(v))); return;
                    case 'f': WriteUInt(buf, at, 4, (uint)BitConverter.SingleToInt32Bits((float)ToDouble(v))); return;
                    case 'd': WriteUInt(buf, at, 8, (ulong)BitConverter.DoubleToInt64Bits(ToDouble(v))); return;
                }
                BigInteger x = v switch
                {
                    bool f => f ? 1 : 0, BigInteger bi => bi, double or float => throw new error("required argument is not an integer"),
                    _ => new BigInteger(Convert.ToInt64(v, CultureInfo.InvariantCulture)),
                };
                bool signed = char.IsLower(it.Code) && it.Code != 'c';
                int bits = it.Size * 8;
                BigInteger lo = signed ? -(BigInteger.One << (bits - 1)) : 0, hi = signed ? (BigInteger.One << (bits - 1)) - 1 : (BigInteger.One << bits) - 1;
                if (x < lo || x > hi)
                    throw new error(signed ? $"'{it.Code}' format requires {lo} <= number <= {hi}" : $"'{it.Code}' format requires 0 <= number <= {hi}");
                WriteUInt(buf, at, it.Size, (ulong)(x & ((BigInteger.One << bits) - 1)));
            }

            void WriteUInt(byte[] buf, int at, int n, ulong v)
            {
                for (int k = 0; k < n; k++) buf[at + (_little ? k : n - 1 - k)] = (byte)(v >> (8 * k));
            }

            static double ToDouble(object? v) => v is BigInteger b ? (double)b : Convert.ToDouble(v, CultureInfo.InvariantCulture);
        }

        public static PyBytes pack(string format, params object?[] v) => Of(format).pack(v);
        public static void pack_into(string format, PyByteArray buffer, long offset, params object?[] v) => Of(format).pack_into(buffer, offset, v);
        public static PyTuple<object?> unpack(string format, object buffer) => Of(format).unpack(buffer);
        public static PyTuple<object?> unpack_from(string format, object buffer, long offset = 0) => Of(format).unpack_from(buffer, offset);
        public static IEnumerable<PyTuple<object?>> iter_unpack(string format, object buffer) => Of(format).iter_unpack(buffer);
        public static long calcsize(string format) => Of(format).size;
        /// <summary>An item of a literal format's unpacked tuple, as its static type (the compiler knows the format).</summary>
        public static T __item<T>(object? v) => v is T t ? t : typeof(T) == typeof(BigInteger) ? (T)(object)(v is long l ? new BigInteger(l) : (BigInteger)v!) : (T)Convert.ChangeType(v, typeof(T), CultureInfo.InvariantCulture)!;
    }
}
